def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Extend any same-colored down-left diagonal pair toward the upper-right.
    for r in range(h - 1):
        for c in range(1, w):
            color = grid[r][c]
            if color != 0 and grid[r + 1][c - 1] == color:
                rr, cc = r, c
                while rr >= 0 and cc < w:
                    out[rr][cc] = color
                    rr -= 1
                    cc += 1
    return out
