def transform(grid):
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])

    # A matching diagonal pair identifies a ray, which continues up-right.
    for r in range(h - 1):
        for c in range(1, w):
            color = grid[r][c]
            if color != bg and grid[r + 1][c - 1] == color:
                rr, cc = r, c
                while rr >= 0 and cc < w:
                    out[rr][cc] = color
                    rr -= 1
                    cc += 1
    return out
